 HEAD+"  <title>Gallery</title>\n  <style>\n    body { font-family: sans-serif; padding: 12px; }\n    .gallery {\n      /* make it a 3-column grid with a gap */\n    }\n    .card { background: #ffe9a8; padding: 24px; border-radius: 12px; text-align: center; }\n    /* add a .card:hover that lifts the card */\n  </style>\n</head>\n<body>\n  <div class=\"gallery\">\n    <div class=\"card\">🍛 Jollof</div>\n    <div class=\"card\">🥘 Egusi</div>\n    <div class=\"card\">🍢 Suya</div>\n    <div class=\"card\">🥭 Mango</div>\n    <div class=\"card\">🍌 Plantain</div>\n    <div class=\"card\">🍉 Melon</div>\n  </div>\n</body>\n</html>",
 HEAD+"  <title>Gallery</title>\n  <style>\n    body { font-family: sans-serif; padding: 12px; }\n    .gallery { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; }\n    .card { background: #ffe9a8; padding: 24px; border-radius: 12px; text-align: center; }\n    .card:hover { transform: translateY(-6px); }\n  </style>\n</head>\n<body>\n  <div class=\"gallery\">\n    <div class=\"card\">🍛 Jollof</div>\n    <div class=\"card\">🥘 Egusi</div>\n    <div class=\"card\">🍢 Suya</div>\n    <div class=\"card\">🥭 Mango</div>\n    <div class=\"card\">🍌 Plantain</div>\n    <div class=\"card\">🍉 Melon</div>\n  </div>\n</body>\n</html>",
 [M('Make .gallery a grid.','.gallery { display: grid; }',"return t.css('.gallery','display')==='grid'"),M('Use 3 columns.','grid-template-columns: 1fr 1fr 1fr;',"return t.css('.gallery','grid-template-columns').split(' ').length===3"),M('Add a gap of 8px or more.','gap: 12px;',"return t.num('.gallery','row-gap')>=8"),M('Add a .card:hover rule with transform.','.card:hover { transform: translateY(-6px); }',"return /\\.card\\s*:hover[^}]*transform/.test(t.src)")],
