W2.append(WP('grade-calculator','Grade Calculator','🎓',3,['real-world'],'Type 3 scores. See the average and a grade letter.','Teachers calculate averages and grades. Your page can too.',['Adding and dividing','if / else if / else','Number()'],
 [('Read 3 scores','Use .value and Number().'),('Average','(a + b + c) / 3'),('Pick a grade','If avg >= 70 say A, else if >= 50 say B, else C.'),('Show it','Put the result in the page.')],['HTML','JavaScript'],[('Number','Number(|)'),('if','if (avg >= 70) {\n  |\n} else if (avg >= 50) {\n} else {\n}')],
 HEAD+"  <title>Grade</title>\n</head>\n<body>\n  <input id=\"a\" placeholder=\"Score 1\"> <input id=\"b\" placeholder=\"Score 2\"> <input id=\"c\" placeholder=\"Score 3\">\n  <button id=\"go\">Work it out</button>\n  <p id=\"out\"></p>\n  <script>\n    var out = document.getElementById('out');\n    document.getElementById('go').addEventListener('click', function () {\n      var a = Number(document.getElementById('a').value);\n      var b = Number(document.getElementById('b').value);\n      var c = Number(document.getElementById('c').value);\n      // 1: avg = (a + b + c) / 3\n      // 2: grade A if avg >= 70, B if >= 50, else C\n      // 3: show: Average 60 - Grade B\n    });\n  </script>\n</body>\n</html>",
 HEAD+"  <title>Grade</title>\n</head>\n<body>\n  <input id=\"a\" placeholder=\"Score 1\"> <input id=\"b\" placeholder=\"Score 2\"> <input id=\"c\" placeholder=\"Score 3\">\n  <button id=\"go\">Work it out</button>\n  <p id=\"out\"></p>\n  <script>\n    var out = document.getElementById('out');\n    document.getElementById('go').addEventListener('click', function () {\n      var a = Number(document.getElementById('a').value);\n      var b = Number(document.getElementById('b').value);\n      var c = Number(document.getElementById('c').value);\n      var avg = (a + b + c) / 3;\n      var grade = 'C';\n      if (avg >= 70) { grade = 'A'; } else if (avg >= 50) { grade = 'B'; }\n      out.textContent = 'Average ' + Math.round(avg) + ' - Grade ' + grade;\n    });\n  </script>\n</body>\n</html>",
 [M('80, 70, 90 should show Average 80 and Grade A.','avg = (a + b + c) / 3',"t.type('#a','80');t.type('#b','70');t.type('#c','90');await t.click('#go');var x=t.text('#out');return /80/.test(x) && /A\\b/.test(x)"),M('50, 60, 40 should show Average 50 and Grade B.','else if (avg >= 50)',"t.type('#a','50');t.type('#b','60');t.type('#c','40');await t.click('#go');var x=t.text('#out');return /50/.test(x) && /B\\b/.test(x)"),M('10, 20, 30 should show Average 20 and Grade C.','The last case is else.',"t.type('#a','10');t.type('#b','20');t.type('#c','30');await t.click('#go');var x=t.text('#out');return /20/.test(x) && /C\\b/.test(x)"),M('Use if and else.','if (...) { } else if (...) { } else { }',"return /if\\s*\\(/.test(t.src) && /else/.test(t.src)")],
 'Ask your teacher how the school grades are worked out.','Add a fourth score.'))
